local Confectioner = {}
local PRODUCTS = {
    sugar_plum = { name = "Sladkorna sliva", sugarCost = 2, fruitCost = 1, time = 2, cost = 18, flavorStrength = 35, happiness = 2, description = "Sladkorna sliva za otroke." },
    candied_peel = { name = "Kandirana lupina", sugarCost = 2, fruitCost = 2, time = 3, cost = 45, flavorStrength = 50, happiness = 3, prestige = 1, description = "Kandirana lupina citrusov." },
    caramel = { name = "Karamela", sugarCost = 3, butterCost = 1, honeyCost = 1, time = 5, cost = 110, flavorStrength = 65, happiness = 4, prestige = 3, description = "Karamela z bogatim okusom." },
    marzipan_shape = { name = "Marcipanasta oblika", almondCost = 2, sugarCost = 2, honeyCost = 1, time = 7, cost = 240, flavorStrength = 80, happiness = 5, prestige = 6, description = "Marcipanasta oblika za slovesnosti." },
    gold_leaf_confection = { name = "Zlatolistna sladica", almondCost = 3, sugarCost = 3, goldCost = 1, honeyCost = 1, spiceCost = 1, time = 10, cost = 560, flavorStrength = 92, happiness = 7, prestige = 13, description = "Sladica z zlatim lističem za plemiče." },
    royal_grand_confection = { name = "Kraljevski veliki sladica", almondCost = 5, sugarCost = 5, goldCost = 2, silverCost = 1, jewelCost = 1, honeyCost = 2, spiceCost = 2, fruitCost = 3, time = 15, cost = 1700, flavorStrength = 100, happiness = 15, prestige = 38, description = "Velika kraljevska sladica z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Sladkarska delavnica", cost = { gold = 320, wood = 130, stone = 200 }, upkeep = 8, qualityBonus = 5 },
    confectionery = { name = "Sladkarnica", cost = { gold = 1000, wood = 250, stone = 400, sugar = 8 }, upkeep = 25, qualityBonus = 18 },
    decorating_room = { name = "Okrasovalnica", cost = { gold = 2400, wood = 350, stone = 700, silver = 40, almond = 8 }, upkeep = 60, qualityBonus = 30 },
    royal_confection_atelier = { name = "Kraljevski atelje sladic", cost = { gold = 9500, wood = 600, stone = 1000, gold = 80, jewel = 25 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 40 },
}
Confectioner.sugarStock = 22; Confectioner.fruitStock = 14; Confectioner.butterCost = 12; Confectioner.honeyStock = 14; Confectioner.almondStock = 10; Confectioner.spiceStock = 10; Confectioner.silverStock = 8; Confectioner.goldStock = 6; Confectioner.jewelStock = 6
Confectioner.productStock = {}; Confectioner.buildings = {}; Confectioner.maker = nil; Confectioner.activeMaking = {}; Confectioner.totalProducts = 0; Confectioner.dayTimer = 0
function Confectioner.init() Confectioner.sugarStock=22; Confectioner.fruitStock=14; Confectioner.butterCost=12; Confectioner.honeyStock=14; Confectioner.almondStock=10; Confectioner.spiceStock=10; Confectioner.silverStock=8; Confectioner.goldStock=6; Confectioner.jewelStock=6; Confectioner.productStock={}; Confectioner.buildings={}; Confectioner.maker=nil; Confectioner.activeMaking={}; Confectioner.totalProducts=0; Confectioner.dayTimer=0; print("[Confectioner] Royal Confectioner System initialized (6 products, 4 buildings)") end
function Confectioner.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Confectioner.maker={name=n or ("Sladkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sladkar najet: %s (spretnost: %d)",Confectioner.maker.name,s),"success") end; return true end
function Confectioner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Confectioner.build(id) local ok,e=Confectioner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Confectioner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Confectioner.getQualityBonus() local b=0; for _,bd in ipairs(Confectioner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Confectioner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.sugarCost and Confectioner.sugarStock<(d.sugarCost or 0) then return false,"Premalo sladkorja" end; if d.fruitCost and Confectioner.fruitStock<(d.fruitCost or 0) then return false,"Premalo sadja" end; if d.butterCost and Confectioner.butterCost<(d.butterCost or 0) then return false,"Premalo masla" end; if d.honeyCost and Confectioner.honeyStock<(d.honeyCost or 0) then return false,"Premalo medu" end; if d.almondCost and Confectioner.almondStock<(d.almondCost or 0) then return false,"Premalo mandljev" end; if d.spiceCost and Confectioner.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.silverCost and Confectioner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and Confectioner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and Confectioner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #Confectioner.buildings==0 then return false,"Potrebna delavnica" end; if not Confectioner.maker then return false,"Potreben sladkar" end; return true end
function Confectioner.make(pt,qty) qty=qty or 5; local ok,e=Confectioner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.sugarCost then Confectioner.sugarStock=Confectioner.sugarStock-d.sugarCost*qty end; if d.fruitCost then Confectioner.fruitStock=Confectioner.fruitStock-d.fruitCost*qty end; if d.butterCost then Confectioner.butterCost=Confectioner.butterCost-d.butterCost*qty end; if d.honeyCost then Confectioner.honeyStock=Confectioner.honeyStock-d.honeyCost*qty end; if d.almondCost then Confectioner.almondStock=Confectioner.almondStock-d.almondCost*qty end; if d.spiceCost then Confectioner.spiceStock=Confectioner.spiceStock-d.spiceCost*qty end; if d.silverCost then Confectioner.silverStock=Confectioner.silverStock-d.silverCost*qty end; if d.goldCost then Confectioner.goldStock=Confectioner.goldStock-d.goldCost*qty end; if d.jewelCost then Confectioner.jewelStock=Confectioner.jewelStock-d.jewelCost*qty end; local t=d.time; if Confectioner.maker then t=math.max(1,t-math.floor(Confectioner.maker.skill/12)) end; table.insert(Confectioner.activeMaking,{id="confection_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flavorStrength=d.flavorStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function Confectioner.completeMaking(m) local q=1.0+(Confectioner.getQualityBonus()/100); if Confectioner.maker then q=q+(Confectioner.maker.skill/180) end; q=math.min(2.0,q); Confectioner.productStock[m.productType]=(Confectioner.productStock[m.productType] or 0)+m.quantity; Confectioner.totalProducts=Confectioner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Confectioner.maker then Confectioner.maker.itemsMade=Confectioner.maker.itemsMade+m.quantity; if math.random()<0.20 then Confectioner.maker.skill=math.min(100,Confectioner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sladica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"confection.completed",{productName=m.productName,flavorStrength=m.flavorStrength,happiness=m.happiness}) end end
function Confectioner.update(dt) if not _G.state then return end; Confectioner.dayTimer=Confectioner.dayTimer+dt; if Confectioner.dayTimer>=30 then Confectioner.dayTimer=0; for i=#Confectioner.activeMaking,1,-1 do local m=Confectioner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Confectioner.completeMaking(m); table.remove(Confectioner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Confectioner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Confectioner.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Confectioner.getStats() return {sugarStock=Confectioner.sugarStock,fruitStock=Confectioner.fruitStock,butterCost=Confectioner.butterCost,honeyStock=Confectioner.honeyStock,almondStock=Confectioner.almondStock,spiceStock=Confectioner.spiceStock,silverStock=Confectioner.silverStock,goldStock=Confectioner.goldStock,jewelStock=Confectioner.jewelStock,productStock=Confectioner.productStock,numBuildings=#Confectioner.buildings,hasMaker=Confectioner.maker~=nil,makerName=Confectioner.maker and Confectioner.maker.name or "—",makerSkill=Confectioner.maker and Confectioner.maker.skill or 0,activeMaking=#Confectioner.activeMaking,totalProducts=Confectioner.totalProducts} end
return Confectioner
